# Downstream benchmark keys
DOWNSTREAM_KEYS = {'arc_easy', 'arc_challenge', 'hellaswag', 'piqa', 'winogrande'}
OOD_KEYS = {'openwebtext_ppl', 'wikipedia_ppl'}

def has_downstream(metrics):
    if not metrics:
        return False
    return any(any(k in mk for k in DOWNSTREAM_KEYS) for mk in metrics.keys())

def has_ood(metrics):
    if not metrics:
        return False
    return any(any(k in mk for k in OOD_KEYS) for mk in metrics.keys())

def is_0_6b(exp_id, exp):
    if '1_7b' in exp_id.lower() or '1.7b' in exp_id.lower():
        return False
    spec = exp.get('spec', {})
    cmd = spec.get('command', '')
    if '1.7b' in cmd.lower() or '1_7b' in cmd.lower():
        return False
    model_name = spec.get('model_name', '')
    if '1.7b' in model_name.lower() or '1_7b' in model_name.lower():
        return False
    return True

