    spec = exp.get('spec', {})
    cmd = spec.get('command', '')
    if 'eval' in cmd.lower() and ('checkpoint' in cmd.lower() or '--checkpoints' in cmd.lower()):
        return True
    if spec.get('checkpoint_source'):
        return True
    if 'eval_perplexity' in cmd or 'eval_downstream' in cmd:
        return True
    return False

# Build eval-experiments lookup: map from checkpoint_source -> list of eval exp_ids
eval_by_source = {}  # source_exp_id -> {'downstream': [...], 'ood': [...]}
for exp_id, exp in exps.items():
    if not is_eval_exp(exp_id, exp):
        continue
    spec = exp.get('spec', {})
    source = spec.get('checkpoint_source', '')
    if source:
        if source not in eval_by_source:
            eval_by_source[source] = {'downstream': [], 'ood': []}
        metrics = exp.get('metrics', {})
        if has_downstream(metrics):
            eval_by_source[source]['downstream'].append((exp_id, exp.get('conclusion', '?'), exp.get('status', '?')))
        if has_ood(metrics):
            eval_by_source[source]['ood'].append((exp_id, exp.get('conclusion', '?'), exp.get('status', '?')))
        # Also check DONE status for in-progress evals
        if exp.get('status') == 'DONE' and not metrics:
            pass
        # Check for pending/running evals that haven't gotten metrics yet
        if exp.get('status') in ('RUNNING', 'QUEUED', 'ALLOCATED', 'ANALYZING', 'PENDING', 'PREPARING'):
            cmd = spec.get('command', '')
            if 'ood' in exp_id.lower() or 'openwebtext' in cmd or 'wikipedia' in cmd:
                eval_by_source[source]['ood'].append((exp_id, exp.get('conclusion', '?'), exp.get('status', '?')))
            if 'downstream' in exp_id.lower() or 'arc' in cmd or 'hellaswag' in cmd:
                eval_by_source[source]['downstream'].append((exp_id, exp.get('conclusion', '?'), exp.get('status', '?')))

print("Eval by source:")
for src, v in sorted(eval_by_source.items()):
    if v['downstream'] or v['ood']:
        print(f"  {src}: downstream={[x[0] for x in v['downstream']]}, ood={[x[0] for x in v['ood']]}")
